public class MyControl : UserControl
{
    private StatusStrip _statusStrip;

    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    public MyControl()
    {
        _statusStrip = new StatusStrip();
        // .NET 9 changed the default ToolStripManager.RenderMode from Professional
        // to System. Explicitly set Professional to preserve .NET 8 appearance.
        _statusStrip.RenderMode = ToolStripRenderMode.Professional;
        Controls.Add(_statusStrip);
    }

    /// <summary>
    /// Safe wrapper around DropDownControl that guards against null.
    /// In .NET 9, passing null throws ArgumentNullException.
    /// </summary>
    public static void ShowDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        if (control is null)
            return;

        editorService.DropDownControl(control);
    }
}

